"""Add provenance reporting objects and indexes."""

from alembic import op

# Keep the revision ID generated by Alembic.
revision = "415b7468c104"
down_revision = "52308b66b24b"
branch_labels = None
depends_on = None


def upgrade() -> None:
    # Index for lookups by decision.
    op.execute("""
        CREATE INDEX IF NOT EXISTS idx_code_change_decision_id
        ON code_change (decision_id)
    """)

    # Partial index for changes with neither interaction nor decision.
    op.execute("""
        CREATE INDEX IF NOT EXISTS idx_code_change_missing_provenance
        ON code_change (project_id, changed_at DESC)
        WHERE interaction_id IS NULL AND decision_id IS NULL
    """)

    # Active engineering decisions.
    op.execute("""
        CREATE VIEW active_decisions AS
        SELECT
            decision_id,
            project_id,
            title,
            decision_type,
            decided_at
        FROM decision
        WHERE status = 'active'
    """)

    # Code changes with both provenance references missing.
    op.execute("""
        CREATE VIEW changes_missing_provenance AS
        SELECT
            change_id,
            project_id,
            file_path,
            origin,
            changed_at
        FROM code_change
        WHERE interaction_id IS NULL
          AND decision_id IS NULL
    """)

    # Project-level provenance summary.
    op.execute("""
        CREATE OR REPLACE FUNCTION get_project_provenance_summary(
            p_project_id uuid
        )
        RETURNS TABLE (
            total_changes bigint,
            ai_exact_changes bigint,
            ai_inferred_changes bigint,
            human_changes bigint,
            missing_provenance bigint,
            uncommitted_changes bigint
        )
        LANGUAGE sql
        STABLE
        AS $$
            SELECT
                COUNT(*),
                COUNT(*) FILTER (WHERE origin = 'ai_exact'),
                COUNT(*) FILTER (WHERE origin = 'ai_inferred'),
                COUNT(*) FILTER (WHERE origin = 'human'),
                COUNT(*) FILTER (
                    WHERE interaction_id IS NULL
                       OR decision_id IS NULL
                ),
                COUNT(*) FILTER (WHERE commit_id IS NULL)
            FROM code_change
            WHERE project_id = p_project_id
        $$;
    """)


def downgrade() -> None:
    op.execute("DROP FUNCTION IF EXISTS get_project_provenance_summary(uuid);")
    op.execute("DROP VIEW IF EXISTS changes_missing_provenance;")
    op.execute("DROP VIEW IF EXISTS active_decisions;")
    op.execute("DROP INDEX IF EXISTS idx_code_change_missing_provenance;")
    op.execute("DROP INDEX IF EXISTS idx_code_change_decision_id;")
